function strapsOk(tape: string): boolean {
  const pair: Record<string, string> = { ")": "(", "]": "[", "}": "{" };
  const stack: string[] = [];
  for (const ch of tape) {
    if (ch in pair) { if (stack.pop() !== pair[ch]) return false; }
    else stack.push(ch);
  }
  return stack.length === 0;
}
